import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

const BarChart = () => {
  const chartRef = useRef(null);

  useEffect(() => {
    // Define chart dimensions
    const width = 800;
    const height = 500;
    const margin = { top: 20, right: 30, bottom: 100, left: 200 };

    // Clear any existing SVG content
    d3.select(chartRef.current).selectAll("*").remove();

    // Create an SVG element in the chartRef container
    const svg = d3
      .select(chartRef.current)
      .attr("width", width)
      .attr("height", height);

    // Load and process the CSV data
    d3.csv(process.env.PUBLIC_URL + "/co-emissions-per-capita.csv").then((data) => {
      // Filter and sort data to get the top 10 countries by emissions in the latest year
      const filteredData = data
        .filter((d) => d["Year"] === "2019") // Filter for the year 2019 or latest year available
        .sort((a, b) => +b["Annual_CO2_emissions_(per_capita)"] - +a["Annual_CO2_emissions_(per_capita)"])
        .slice(0, 10);

      // Create scales for x and y axes
      const x = d3
        .scaleBand()
        .domain(filteredData.map((d) => d["Entity"]))
        .range([margin.left, width - margin.right])
        .padding(0.1);

      const y = d3
        .scaleLinear()
        .domain([0, d3.max(filteredData, (d) => +d["Annual_CO2_emissions_(per_capita)"]) || 0])
        .nice()
        .range([height - margin.bottom, margin.top]);

      // Tooltip
      const tooltip = d3.select('body').append('div')
        .attr('class', 'racebar-tooltip')
        .style('position', 'absolute')
        .style('background', '#fffbe9')
        .style('color', '#6b4f27')
        .style('border', '1.5px solid #d6c7b0')
        .style('border-radius', '6px')
        .style('padding', '6px 12px')
        .style('font-family', 'Georgia, Times New Roman, Times, serif')
        .style('font-size', '0.95rem')
        .style('box-shadow', '0 2px 8px rgba(120, 90, 40, 0.10)')
        .style('pointer-events', 'none')
        .style('z-index', 1000)
        .style('opacity', 0);
      // Add X axis to the chart
      svg
        .append("g")
        .attr("transform", `translate(0,${height - margin.bottom})`)
        .call(d3.axisBottom(x))
        .selectAll("text")
        .attr("transform", "rotate(-45)")
        .style("text-anchor", "end");

      // Add Y axis to the chart
      svg
        .append("g")
        .attr("transform", `translate(${margin.left},0)`)
        .call(d3.axisLeft(y).ticks(10));

      // Add bars
      svg
        .selectAll(".bar")
        .data(filteredData)
        .enter()
        .append("rect")
        .attr("class", "bar")
        .attr("x", (d) => x(d["Entity"]) || 0)
        .attr("y", (d) => y(+d["Annual_CO2_emissions_(per_capita)"]))
        .attr("width", x.bandwidth())
        .attr("height", (d) => height - margin.bottom - y(+d["Annual_CO2_emissions_(per_capita)"]))
        .attr("fill", "steelblue")
        .on("mouseover", function (event, d) {
          tooltip.transition().duration(200).style("opacity", 0.95);
          tooltip.html(`<strong>Country:</strong> ${d["Entity"]}<br><strong>Emissions:</strong> ${(+d["Annual_CO2_emissions_(per_capita)"]).toFixed(2)} tons/capita`)
              .style("left", (event.clientX + 16) + "px")
              .style("top", (event.clientY - 16) + "px");

          d3.select(this)
            .style("transform", "scale(1.01,1.01)")
            .style("transform-origin", "50% 50%")
            .transition()
            .duration(150)
            .style("opacity", 0.8)
        })
        .on("mouseout", function () {
          d3.select(this)
            .style("transform", "scale(1,1)")
            .style("transform-origin", "50% 50%")
            .transition()
            .duration(500)
            .style("opacity", 1)

            tooltip.transition().duration(500).style("opacity", 0);
        });


    });
  }, []);

  return (
    <div>
      {/* <h2 style={{marginTop: '10px', color: 'black'}}>Top CO₂ Emitters Over Time</h2> */}
      <svg ref={chartRef}></svg>
    </div>
  );
};

export default BarChart;
