import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

const CO2Heatmap = ({ year }) => {
  const svgRef = useRef(null);

  useEffect(() => {
    // Load the CSV data
    d3.csv(process.env.PUBLIC_URL + '/co2-fossil-plus-land-use.csv').then((data) => {
      // Filter data for the specified year and calculate total emissions, columns used from the csv file
      const filteredData = data
        .filter((d) => +d['Year'] === year)
        .map((d) => ({
          entity: d['Entity'],
          fossilEmissions: +d['Annual_CO2_emissions'],
          landUseEmissions: +d['Annual_CO2_emissions_from_land_use_change'],
          totalEmissions: +d['Annual_CO2_emissions'] + +d['Annual_CO2_emissions_from_land_use_change'],
        }))
        .sort((a, b) => b.totalEmissions - a.totalEmissions)
        .slice(0, 10);

      // Set dimensions and margins for the heatmap
      const width = 800;
      const height = 400;
      const margin = { top: 50, right: 30, bottom: 40, left: 200 };

      // Clear any previous SVG content
      d3.select(svgRef.current).selectAll('*').remove();

      // Create the SVG container
      const svg = d3
        .select(svgRef.current)
        .attr('width', width + margin.left + margin.right)
        .attr('height', height + margin.top + margin.bottom)
        .append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

      // Remove any existing tooltip
      d3.selectAll('.racebar-tooltip').remove();
      // Create tooltip div
      const tooltip = d3.select('body')
        .append('div')
        .attr('class', 'racebar-tooltip')
        .style('position', 'absolute')
        .style('background', '#fffbe9')
        .style('color', '#6b4f27')
        .style('border', '1.5px solid #d6c7b0')
        .style('border-radius', '6px')
        .style('padding', '6px 12px')
        .style('font-family', 'Georgia, Times New Roman, Times, serif')
        .style('font-size', '0.95rem')
        .style('box-shadow', '0 2px 8px rgba(120, 90, 40, 0.10)')
        .style('pointer-events', 'none')
        .style('z-index', 1000)
        .style('display', 'none');

      // Define scales for the x-axis (emission type) and y-axis (countries)
      const x = d3
        .scaleBand()
        .domain(['Fossil Fuel Emissions', 'Land-Use Change Emissions'])
        .range([0, width])
        .padding(0.05);

      const y = d3
        .scaleBand()
        .domain(filteredData.map((d) => d.entity))
        .range([0, height])
        .padding(0.05);

      // Define color scale for the heatmap
      const colorScale = d3
        .scaleSequential(d3.interpolateOrRd)
        .domain([0, d3.max(filteredData, (d) => Math.max(d.fossilEmissions, d.landUseEmissions))]);

      // Add x-axis
      svg
        .append('g')
        .attr('transform', `translate(0,${height})`)
        .call(d3.axisBottom(x));

      // Add y-axis
      svg.append('g').call(d3.axisLeft(y));

      // Create the heatmap cells
      svg
        .selectAll('rect')
        .data(filteredData.flatMap((d) => [
          { entity: d.entity, type: 'Fossil Fuel Emissions', value: d.fossilEmissions },
          { entity: d.entity, type: 'Land-Use Change Emissions', value: d.landUseEmissions },
        ]))
        .enter()
        .append('rect')
        .attr('x', (d) => x(d.type))
        .attr('y', (d) => y(d.entity))
        .attr('width', x.bandwidth())
        .attr('height', y.bandwidth())
        .attr('fill', (d) => colorScale(d.value))
        .on('mouseover', function(event, d) {
          tooltip
            .style('display', 'block')
            .html(`<strong>${d.entity}</strong><br/>${d.type}: ${d.value.toLocaleString()} tons`)
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mousemove', function(event) {
          tooltip
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mouseout', function() {
          tooltip.style('display', 'none');
        });
    });
  }, [year]);

  return (
    <div style={{ padding: '20px', background: 'white' }}>
      {/* <h2>CO₂ Emissions Heatmap (Top 10 Countries) - {year}</h2> */}
      <svg ref={svgRef}></svg>
    </div>
  );
};

export default CO2Heatmap;
