import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

const AlluvialDiagram = () => {
  const svgRef = useRef(null);

  useEffect(() => {
    // Fetch and process data
    fetch(process.env.PUBLIC_URL + '/co2-fossil-plus-land-use.csv')
      .then(res => res.text())
      .then(rawData => {
        const data = d3.csvParse(rawData, d3.autoType);
        // Map country to continent (small subset for clarity)
        const countryToContinent = {
          Brazil: 'South America',
          China: 'Asia',
          India: 'Asia',
          Russia: 'Europe',
          Germany: 'Europe',
          Japan: 'Asia',
          Australia: 'Oceania',
          'United States': 'North America',
        };
        const categories = [
          { key: 'Annual_CO2_emissions', label: 'Fossil Fuel' },
          { key: 'Annual_CO2_emissions_from_land_use_change', label: 'Land Use Change' }
        ];
        // Build nodes and links
        const continents = Array.from(new Set(Object.values(countryToContinent)));
        const countries = Object.keys(countryToContinent);
        // Layout columns
        // Lines show the flow of CO₂ emissions from continent → country → category
        const width = 1200, height = 450, colWidth = 320, nodeHeight = 22, nodeGap = 28, topPad = 30;
        const columns = [continents, countries, categories.map(c => c.label)];
        const nodePos = {};
        columns.forEach((col, colIdx) => {
          let y = topPad;
          col.forEach((id, i) => {
            nodePos[id] = { x: colIdx * colWidth + 120, y };
            y += nodeHeight + nodeGap;
          });
        });
        // Build links
        const links = [];
        // Continent → Country
        countries.forEach(country => {
          const continent = countryToContinent[country];
          // Find the most recent year with data for this country
          const countryRows = data.filter(d => d.Entity === country && d['Annual_CO2_emissions_including_land_use_change'] != null && !isNaN(d['Annual_CO2_emissions_including_land_use_change']));
          let countryData = countryRows.find(d => d.Year === 2020);
          if (!countryData && countryRows.length > 0) {
            // Use the most recent year available
            countryData = countryRows.reduce((a, b) => (a.Year > b.Year ? a : b));
          }
          const value = countryData ? (countryData['Annual_CO2_emissions_including_land_use_change'] || 0) : 0;
          links.push({ source: continent, target: country, value });
        });
        // Country → Category
        countries.forEach(country => {
          // Find the most recent year with data for this country
          const countryRows = data.filter(d => d.Entity === country);
          let countryData = countryRows.find(d => d.Year === 2020);
          if (!countryData && countryRows.length > 0) {
            countryData = countryRows.reduce((a, b) => (a.Year > b.Year ? a : b));
          }
          categories.forEach(cat => {
            const value = countryData && countryData[cat.key] ? countryData[cat.key] : 0;
            links.push({ source: country, target: cat.label, value });
          });
        });
        // Draw SVG
        d3.select(svgRef.current).selectAll('*').remove();
        d3.selectAll('.racebar-tooltip').remove();
        const tooltip = d3.select('body')
          .append('div')
          .attr('class', 'racebar-tooltip')
          .style('position', 'absolute')
          .style('background', '#fffbe9')
          .style('color', '#6b4f27')
          .style('border', '1.5px solid #d6c7b0')
          .style('border-radius', '6px')
          .style('padding', '6px 12px')
          .style('font-family', 'Georgia, Times New Roman, Times, serif')
          .style('font-size', '0.95rem')
          .style('box-shadow', '0 2px 8px rgba(120, 90, 40, 0.10)')
          .style('pointer-events', 'none')
          .style('z-index', 1000)
          .style('display', 'none');
        // Add subtle paper background
        const svg = d3.select(svgRef.current)
          .attr('width', width)
          .attr('height', height);
        svg.append('rect')
          .attr('x', 0)
          .attr('y', 0)
          .attr('width', width)
          .attr('height', height)
          .attr('fill', 'url(#paper-bg)');
        // Add SVG defs for background texture and link shadow
        // svg.append('defs').html(`
        //   <radialGradient id="paper-bg" cx="50%" cy="50%" r="80%">
        //     <stop offset="0%" stop-color="#fffbe9"/>
        //     <stop offset="100%" stop-color="#f4e7c4"/>
        //   </radialGradient>
        //   <filter id="node-shadow" x="-20%" y="-20%" width="140%" height="140%">
        //     <feDropShadow dx="0" dy="2" stdDeviation="2" flood-color="#bcae7c" flood-opacity="0.25"/>
        //   </filter>
        //   <filter id="link-shadow" x="-20%" y="-20%" width="140%" height="140%">
        //     <feDropShadow dx="0" dy="1" stdDeviation="1.5" flood-color="#a68b5b" flood-opacity="0.18"/>
        //   </filter>
        // `);
        // Draw links
        svg.selectAll('.alluvial-link')
          .data(links)
          .enter()
          .append('path')
          .attr('class', 'alluvial-link')
          .attr('d', d => {
            const s = nodePos[d.source];
            const t = nodePos[d.target];
            return `M${s.x + 140} ${s.y + nodeHeight/2} C ${s.x + 180} ${s.y + nodeHeight/2}, ${t.x - 40} ${t.y + nodeHeight/2}, ${t.x} ${t.y + nodeHeight/2}`;
          })
          .attr('fill', 'none')
          .attr('stroke', d => d3.interpolateRgb('#bcae7c', '#6b4f27')(0.4 + 0.6 * Math.random()))
          .attr('stroke-width', d => Math.max(2, Math.log(d.value + 1)))
          .attr('opacity', 0.55)
          .attr('filter', 'url(#link-shadow)')
         .on('mouseover', function(event, d) {
           d3.select(this)
             .attr('opacity', 0.95)
             .attr('stroke-width', Math.max(4, Math.log(d.value + 1)));
           tooltip
             .style('display', 'block')
             .html(`<strong>${d.source} → ${d.target}</strong><br/>Value: ${d.value.toLocaleString(undefined, {maximumFractionDigits: 2})}`)
             .style('left', (event.clientX + 16) + 'px')
             .style('top', (event.clientY - 16) + 'px');
         })
         .on('mousemove', function(event) {
           tooltip
             .style('left', (event.clientX + 16) + 'px')
             .style('top', (event.clientY - 16) + 'px');
         })
         .on('mouseout', function(event, d) {
           d3.select(this)
             .attr('opacity', 0.55)
             .attr('stroke-width', Math.max(2, Math.log(d.value + 1)));
           tooltip.style('display', 'none');
         });
        // Draw nodes
        Object.entries(nodePos).forEach(([id, pos]) => {
          svg.append('rect')
            .attr('x', pos.x)
            .attr('y', pos.y)
            .attr('width', 140)
            .attr('height', nodeHeight)
            .attr('fill', '#fffbe9')
            .attr('stroke', '#bcae7c')
            .attr('stroke-width', 2)
            .attr('rx', 8)
            .attr('filter', 'url(#node-shadow)');
          svg.append('text')
            .attr('x', pos.x + 70)
            .attr('y', pos.y + nodeHeight/2 + 5)
            .attr('text-anchor', 'middle')
            .attr('font-size', 15)
            .attr('font-family', 'Georgia, Times New Roman, Times, serif')
            .attr('fill', '#6b4f27')
            .attr('font-weight', 'bold')
            .text(id);
        });
      });
  }, []);

  return (
    <div style={{ padding: '0 20px 0 20px', background: 'none', display: 'flex', justifyContent: 'center', alignItems: 'flex-start' }}>
      <svg ref={svgRef}></svg>
    </div>
  );
};

export default AlluvialDiagram;
