import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';

const RaceBarChart = () => {
  const svgRef = useRef(null);
  const [playing, setPlaying] = useState(true);
  const [speed, setSpeed] = useState(1000); // ms
  const [speedMultiplier, setSpeedMultiplier] = useState(1);
  const [yearIndex, setYearIndex] = useState(0);
  const yearsRef = useRef([]);
  const dataByYearRef = useRef(new Map());
  const intervalRef = useRef(null);
  const tooltipRef = useRef(null);

  // Animation and chart logic
  useEffect(() => {
    let isMounted = true;
    d3.csv(process.env.PUBLIC_URL + '/co-emissions-per-capita.csv').then((data) => {
      if (!isMounted) return;
      const parsedData = data.map((d) => ({
        country: d['Entity'],
        year: +d['Year'],
        emissions: +d['Annual_CO2_emissions_(per_capita)'],
      }));
      const dataByYear = d3.group(parsedData, (d) => d.year);
      dataByYearRef.current = dataByYear;
      const years = Array.from(dataByYear.keys()).sort((a, b) => a - b);
      yearsRef.current = years;
      setYearIndex(0);
      drawChart(years[0], dataByYear, years);
    });
    return () => { isMounted = false; };
  }, []);

  // Animation interval effect
  useEffect(() => {
    if (!playing || yearsRef.current.length === 0) return;
    intervalRef.current && clearInterval(intervalRef.current);
    intervalRef.current = setInterval(() => {
      setYearIndex((prev) => {
        const next = (prev + 1) % yearsRef.current.length;
        drawChart(yearsRef.current[next], dataByYearRef.current, yearsRef.current);
        return next;
      });
    }, speed);
    return () => clearInterval(intervalRef.current);
  }, [playing, speed]);

  // Draw chart when yearIndex changes (if not animating)
  useEffect(() => {
    if (!playing && yearsRef.current.length > 0) {
      drawChart(yearsRef.current[yearIndex], dataByYearRef.current, yearsRef.current);
    }
    // eslint-disable-next-line
  }, [yearIndex]);

  const drawChart = (year, dataByYear, years) => {
    if (!dataByYear || !years) return;
    const yearData = dataByYear.get(year) || [];
    const width = 900;
    const height = 500;
    const margin = { top: 50, right: 50, bottom: 70, left: 120 };
    d3.select(svgRef.current).selectAll('*').remove();
    // Ensure tooltip div exists and is referenced
    d3.selectAll('.racebar-tooltip').remove();
    let tooltip = d3.select('body')
      .append('div')
      .attr('class', 'racebar-tooltip')
      .style('position', 'absolute')
      .style('background', '#fffbe9')
      .style('color', '#6b4f27')
      .style('border', '1.5px solid #d6c7b0')
      .style('border-radius', '6px')
      .style('padding', '6px 12px')
      .style('font-family', 'Georgia, Times New Roman, Times, serif')
      .style('font-size', '0.95rem')
      .style('box-shadow', '0 2px 8px rgba(120, 90, 40, 0.10)')
      .style('pointer-events', 'none')
      .style('z-index', 1000)
      .style('display', 'none');
    tooltipRef.current = tooltip;
    const svg = d3
      .select(svgRef.current)
      .attr('width', width + margin.left + margin.right)
      .attr('height', height + margin.top + margin.bottom)
      .append('g')
      .attr('transform', `translate(${margin.left},${margin.top})`);
    const x = d3.scaleLinear().range([0, width]);
    const y = d3.scaleBand().range([0, height]).padding(0.1);
    const color = d3.scaleOrdinal(d3.schemeTableau10);
    const xAxis = svg.append('g').attr('transform', `translate(0,${height})`);
    const yAxis = svg.append('g');
    const yearText = svg
      .append('text')
      .attr('class', 'year-label')
      .attr('x', width / 2)
      .attr('y', -20)
      .attr('text-anchor', 'middle')
      .attr('font-size', '24px')
      .attr('font-weight', 'bold');
    const topEmitters = yearData
      .filter((d) => !isNaN(d.emissions))
      .sort((a, b) => b.emissions - a.emissions)
      .slice(0, 10);
    x.domain([0, d3.max(topEmitters, (d) => d.emissions)]);
    y.domain(topEmitters.map((d) => d.country));
    xAxis.transition().call(d3.axisBottom(x));
    yAxis.transition().call(d3.axisLeft(y));
    const bars = svg.selectAll('.bar').data(topEmitters, (d) => d.country);
    bars
      .enter()
      .append('rect')
      .attr('class', 'bar')
      .attr('x', 0)
      .attr('y', (d) => y(d.country))
      .attr('height', y.bandwidth())
      .attr('width', (d) => x(d.emissions))
      .attr('fill', (d) => color(d.country))
      .on('mouseover', function(event, d) {
        if (tooltipRef.current) {
          tooltipRef.current
            .style('display', 'block')
            .html(`<strong>${d.country}</strong><br/>Emissions: ${d.emissions.toFixed(2)} tons`)
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        }
      })
      .on('mousemove', function(event) {
        if (tooltipRef.current) {
          tooltipRef.current
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        }
      })
      .on('mouseout', function() {
        if (tooltipRef.current) {
          tooltipRef.current.style('display', 'none');
        }
      });
    bars
      .attr('y', (d) => y(d.country))
      .attr('height', y.bandwidth())
      .attr('width', (d) => x(d.emissions))
      .attr('fill', (d) => color(d.country));
    bars.exit().remove();
    svg
      .selectAll('.label')
      .data(topEmitters, (d) => d.country)
      .join(
        (enter) =>
          enter
            .append('text')
            .attr('class', 'label')
            .attr('x', (d) => x(d.emissions) + 5)
            .attr('y', (d) => y(d.country) + y.bandwidth() / 2)
            .attr('dy', '.35em')
            .text((d) => d.emissions.toFixed(2)),
        (update) =>
          update
            .attr('x', (d) => x(d.emissions) + 5)
            .attr('y', (d) => y(d.country) + y.bandwidth() / 2)
            .text((d) => d.emissions.toFixed(2)),
        (exit) => exit.remove()
      );
    yearText.text(`Year: ${year}`);
  };

  return (
    <div>
      <style>{`
        .racebar-btn {
          background: #f8f5f1;
          color: #6b4f27;
          border: 2px solid #d6c7b0;
          border-radius: 6px;
          padding: 4px 10px;
          margin-right: 6px;
          font-size: 0.92rem;
          font-family: 'Georgia', 'Times New Roman', Times, serif;
          font-weight: 600;
          box-shadow: 0 1px 4px rgba(120, 90, 40, 0.08), 0 1px 0 #e9e2d0 inset;
          cursor: pointer;
          transition: background 0.2s, color 0.2s, box-shadow 0.2s, transform 0.1s;
          outline: none;
          position: relative;
        }
        .racebar-btn:disabled {
          background: #ede7df;
          color: #b6a48a;
          border-color: #e0d6c3;
          cursor: not-allowed;
          box-shadow: none;
        }
        .racebar-btn:not(:disabled):hover {
          background: #f3e9d7;
          color: #a67c52;
          box-shadow: 0 4px 16px rgba(120, 90, 40, 0.18);
          transform: translateY(-2px) scale(1.04);
        }
        .racebar-btn:not(:disabled):active {
          background: #ede7df;
          color: #6b4f27;
          transform: scale(0.98);
        }
        .racebar-btn.speed {
          border-left: 5px solid #c97b3b;
          background: linear-gradient(90deg, #f8f5f1 90%, #f3d6b6 100%);
          box-shadow: 0 1px 4px rgba(201, 123, 59, 0.08), 0 1px 0 #e9e2d0 inset;
        }
        .racebar-btn.speed:after {
          content: '';
          position: absolute;
          top: 0; left: 0;
          width: 0; height: 0;
          border-top: 10px solid #c97b3b;
          border-right: 10px solid transparent;
          border-radius: 0 0 4px 0;
          z-index: 1;
          opacity: 0.18;
        }
      `}</style>
      <div style={{ marginBottom: 10 }}>
        <button className="racebar-btn" onClick={() => setPlaying(true)} disabled={playing}>Play</button>
        <button className="racebar-btn" onClick={() => setPlaying(false)} disabled={!playing}>Pause</button>
        <button
          className="racebar-btn speed"
          onClick={() => {
            let nextMultiplier, nextSpeed;
            if (speedMultiplier === 1) { nextMultiplier = 2; nextSpeed = 500; }
            else if (speedMultiplier === 2) { nextMultiplier = 3; nextSpeed = 333; }
            else if (speedMultiplier === 3) { nextMultiplier = 4; nextSpeed = 250; }
            else if (speedMultiplier === 4) { nextMultiplier = 5; nextSpeed = 200; }
            else { nextMultiplier = 1; nextSpeed = 1000; }
            setSpeedMultiplier(nextMultiplier);
            setSpeed(nextSpeed);
          }}
        >
          Speed: {speedMultiplier}x
        </button>
      </div>
      {/* <h2 style={{marginTop: '10px', color: 'black'}}>Top CO₂ Emitters Over Time</h2> */}
      <svg ref={svgRef}></svg>
    </div>
  );
};

export default RaceBarChart;
