import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

const TimelineChart = () => {
  const svgRef = useRef(null);

  useEffect(() => {
    Promise.all([
      d3.text(process.env.PUBLIC_URL + '/new_york_min.csv'),
      d3.text(process.env.PUBLIC_URL + '/new_york_max.csv'),
      d3.text(process.env.PUBLIC_URL + '/new_york_avg.csv'),
    ]).then(([minText, maxText, avgText]) => {
      function parseNYCSV(text) {
        const lines = text.trim().split('\n').slice(4);
        return lines.map(line => {
          const [Date, Value] = line.split(',');
          return { month: Date, value: +Value };
        });
      }
      const minData = parseNYCSV(minText);
      const maxData = parseNYCSV(maxText);
      const avgData = parseNYCSV(avgText);
      const months = minData.map(d => d.month);
      const data = months.map((month, i) => ({
        month,
        min: minData[i]?.value,
        max: maxData[i]?.value,
        mean: avgData[i]?.value,
      }));
      const filtered = data.filter(d => d.min !== -99 && d.max !== -99 && d.mean !== -99);

      const width = 800;
      const height = 400;
      const margin = { top: 40, right: 40, bottom: 50, left: 80 };
      d3.select(svgRef.current).selectAll('*').remove();
      d3.selectAll('.racebar-tooltip').remove();
      const tooltip = d3.select('body')
        .append('div')
        .attr('class', 'racebar-tooltip')
        .style('position', 'absolute')
        .style('background', '#fffbe9')
        .style('color', '#6b4f27')
        .style('border', '1.5px solid #d6c7b0')
        .style('border-radius', '6px')
        .style('padding', '6px 12px')
        .style('font-family', 'Georgia, Times New Roman, Times, serif')
        .style('font-size', '0.95rem')
        .style('box-shadow', '0 2px 8px rgba(120, 90, 40, 0.10)')
        .style('pointer-events', 'none')
        .style('z-index', 1000)
        .style('display', 'none');

      // X: months (as numbers)
      const parseMonth = d3.timeParse('%Y%m');
      // Map months to short names using the month number in YYYYMM
      const monthsShort = ['Ja','F','M','April','Ma','June','July','A','S','O','N','D'];
      const filteredWithShort = filtered.map(d => {
        const monthNum = parseInt(d.month.slice(4, 6), 10) - 1;
        return { ...d, monthShort: monthsShort[monthNum] };
      });
      const x = d3.scalePoint()
        .domain(filteredWithShort.map(d => d.monthShort))
        .range([0, width]);
      // Y: temperature
      const y = d3.scaleLinear()
        .domain([20, 80])
        .range([height, 0]);

      const svg = d3.select(svgRef.current)
        .attr('width', width + margin.left + margin.right)
        .attr('height', height + margin.top + margin.bottom)
        .style('background', 'none') // Ensure SVG is transparent
        .append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

      // X axis
      svg.append('g')
        .attr('transform', `translate(0,${height})`)
        .call(d3.axisBottom(x));
      // Y axis
      svg.append('g').call(d3.axisLeft(y));

      svg.append('text')
        .attr('x', width / 2)
        .attr('y', height + margin.bottom - 10)
        .attr('text-anchor', 'middle')
        .attr('font-size', '1.1rem')
        .attr('fill', '#6b4f27')
        .text('Month');
      svg.append('text')
        .attr('x', -height / 2)
        .attr('y', -margin.left + 20)
        .attr('text-anchor', 'middle')
        .attr('transform', 'rotate(-90)')
        .attr('font-size', '1.1rem')
        .attr('fill', '#6b4f27')
        .text('Temperature (°F)');

      // Colors for 2023
      const minColor = '#235390';
      const maxColor = '#e74c3c';

      // Line generators
      const lineMin = d3.line()
        .x((d) => x(d.monthShort))
        .y(d => y(d.min));
      const lineMax = d3.line()
        .x((d) => x(d.monthShort))
        .y(d => y(d.max));

      // Draw min line
      svg.append('path')
        .datum(filteredWithShort)
        .attr('fill', 'none')
        .attr('stroke', minColor)
        .attr('stroke-width', 2.5)
        .attr('d', lineMin);
      // Draw max line
      svg.append('path')
        .datum(filteredWithShort)
        .attr('fill', 'none')
        .attr('stroke', maxColor)
        .attr('stroke-width', 2.5)
        .attr('d', lineMax);

      // Draw min scatter
      svg.selectAll('.min-dot')
        .data(filteredWithShort)
        .enter()
        .append('circle')
        .attr('class', 'min-dot')
        .attr('cx', d => x(d.monthShort))
        .attr('cy', d => y(d.min))
        .attr('r', 4)
        .attr('fill', minColor)
        .on('mouseover', function(event, d) {
          tooltip
            .style('display', 'block')
            .html(`<strong>${d.monthShort} 2023</strong><br/>Min: ${d.min}°F`)
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mousemove', function(event) {
          tooltip
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mouseout', function() {
          tooltip.style('display', 'none');
        });
      // Draw max scatter
      svg.selectAll('.max-dot')
        .data(filteredWithShort)
        .enter()
        .append('circle')
        .attr('class', 'max-dot')
        .attr('cx', d => x(d.monthShort))
        .attr('cy', d => y(d.max))
        .attr('r', 4)
        .attr('fill', maxColor)
        .on('mouseover', function(event, d) {
          tooltip
            .style('display', 'block')
            .html(`<strong>${d.monthShort} 2023</strong><br/>Max: ${d.max}°F`)
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mousemove', function(event) {
          tooltip
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mouseout', function() {
          tooltip.style('display', 'none');
        });

      // Draw mean (average) scatter
      const meanColor = '#c97b3b';
      svg.selectAll('.mean-dot')
        .data(filteredWithShort)
        .enter()
        .append('circle')
        .attr('class', 'mean-dot')
        .attr('cx', d => x(d.monthShort))
        .attr('cy', d => y(d.mean))
        .attr('r', 5)
        .attr('fill', meanColor)
        .attr('stroke', '#6b4f27')
        .attr('stroke-width', 1.5)
        .on('mouseover', function(event, d) {
          tooltip
            .style('display', 'block')
            .html(`<strong>${d.monthShort} 2023</strong><br/>Mean: ${d.mean}°F`)
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mousemove', function(event) {
          tooltip
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mouseout', function() {
          tooltip.style('display', 'none');
        });

    });
  }, []);

  return (
    <div style={{ padding: '20px', background: 'none' }}>
      <svg ref={svgRef}></svg>
    </div>
  );
};

export default TimelineChart; 