import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

const RadarChart = () => {
  const svgRef = useRef(null);

  useEffect(() => {
    Promise.all([
      d3.text(process.env.PUBLIC_URL + '/montana_2019average.csv'),
      d3.text(process.env.PUBLIC_URL + '/montana_2024average.csv'),
    ]).then(([csv2019, csv2024]) => {
      function parseCSV(text) {
        const lines = text.trim().split('\n').slice(4);
        return lines.map(line => {
          const [Date, Value] = line.split(',');
          return { month: Date, value: +Value };
        }).filter(d => d.value !== -99);
      }
      const data2019 = parseCSV(csv2019);
      const data2024 = parseCSV(csv2024);
      const monthsShort = ['Jan','Feb','Mar','Apr','May','June','July','Aug','Sep','Oct','Nov','Dec'];
      const values2019 = data2019.map(d => d.value);
      const values2024 = data2024.map(d => d.value);
      const N = 12;

      // Radar chart dimensions
      const width = 400;
      const height = 400;
      const margin = 40;
      const radius = Math.min(width, height) / 2 - margin;
      const centerX = width / 2;
      const centerY = height / 2;

      d3.select(svgRef.current).selectAll('*').remove();
      d3.selectAll('.racebar-tooltip').remove();
      const tooltip = d3.select('body')
        .append('div')
        .attr('class', 'racebar-tooltip')
        .style('position', 'absolute')
        .style('background', '#fffbe9')
        .style('color', '#6b4f27')
        .style('border', '1.5px solid #d6c7b0')
        .style('border-radius', '6px')
        .style('padding', '6px 12px')
        .style('font-family', 'Georgia, Times New Roman, Times, serif')
        .style('font-size', '0.95rem')
        .style('box-shadow', '0 2px 8px rgba(120, 90, 40, 0.10)')
        .style('pointer-events', 'none')
        .style('z-index', 1000)
        .style('display', 'none');
      const svg = d3.select(svgRef.current)
        .attr('width', width)
        .attr('height', height)
        .append('g')
        .attr('transform', `translate(${centerX},${centerY})`);

      // Y scale (radius)
      const minTemp = 20;
      const maxTemp = 50;
      const r = d3.scaleLinear()
        .domain([minTemp, maxTemp])
        .range([0, radius]);

      // Draw grid circles and labels
      const gridLevels = [25, 30, 35, 40, 45, 50];
      gridLevels.forEach(temp => {
        svg.append('circle')
          .attr('r', r(temp))
          .attr('fill', 'none')
          .attr('stroke', '#d3d3d3')
          .attr('stroke-width', 1);
        svg.append('text')
          .attr('x', 0)
          .attr('y', -r(temp) - 4)
          .attr('text-anchor', 'middle')
          .attr('font-size', '12px')
          .attr('fill', '#888')
          .text(temp);
      });

      // Draw axes (one per month)
      for (let i = 0; i < N; i++) {
        const angle = (Math.PI * 2 * i) / N;
        svg.append('line')
          .attr('x1', 0)
          .attr('y1', 0)
          .attr('x2', r(maxTemp) * Math.sin(angle))
          .attr('y2', -r(maxTemp) * Math.cos(angle))
          .attr('stroke', '#d3d3d3')
          .attr('stroke-width', 1);
        // Month label
        svg.append('text')
          .attr('x', (r(maxTemp) + 12) * Math.sin(angle))
          .attr('y', -(r(maxTemp) + 12) * Math.cos(angle) + 4)
          .attr('text-anchor', 'middle')
          .attr('font-size', '13px')
          .attr('fill', '#888')
          .text(monthsShort[i]);
      }

      // Draw radar lines
      const line = d3.lineRadial()
        .radius((d) => r(d))
        .angle((d, i) => (Math.PI * 2 * i) / N)
        .curve(d3.curveCardinalClosed);
      svg.append('path')
        .datum(values2019)
        .attr('fill', 'none')
        .attr('stroke', '#235390')
        .attr('stroke-width', 4)
        .attr('d', line);
      svg.append('path')
        .datum(values2024)
        .attr('fill', 'none')
        .attr('stroke', '#e74c3c')
        .attr('stroke-width', 4)
        .attr('d', line);

      // Draw points for both years
      svg.selectAll('.radar-point-2019')
        .data(values2019)
        .enter()
        .append('circle')
        .attr('class', 'radar-point-2019')
        .attr('cx', (d, i) => r(d) * Math.sin((Math.PI * 2 * i) / N))
        .attr('cy', (d, i) => -r(d) * Math.cos((Math.PI * 2 * i) / N))
        .attr('r', 5)
        .attr('fill', '#235390')
        .attr('stroke', '#fff')
        .attr('stroke-width', 2)
        .on('mouseover', function(event, d, i) {
          tooltip
            .style('display', 'block')
            .html(`<strong>${monthsShort[i]} 2019</strong><br/>Mean: ${d}°F`)
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mousemove', function(event) {
          tooltip
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mouseout', function() {
          tooltip.style('display', 'none');
        });
      svg.selectAll('.radar-point-2024')
        .data(values2024)
        .enter()
        .append('circle')
        .attr('class', 'radar-point-2024')
        .attr('cx', (d, i) => r(d) * Math.sin((Math.PI * 2 * i) / N))
        .attr('cy', (d, i) => -r(d) * Math.cos((Math.PI * 2 * i) / N))
        .attr('r', 5)
        .attr('fill', '#e74c3c')
        .attr('stroke', '#fff')
        .attr('stroke-width', 2)
        .on('mouseover', function(event, d, i) {
          tooltip
            .style('display', 'block')
            .html(`<strong>${monthsShort[i]} 2024</strong><br/>Mean: ${d}°F`)
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mousemove', function(event) {
          tooltip
            .style('left', (event.clientX + 16) + 'px')
            .style('top', (event.clientY - 16) + 'px');
        })
        .on('mouseout', function() {
          tooltip.style('display', 'none');
        });

    });
  }, []);

  return (
    <div style={{ padding: '20px', background: 'none', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
      <svg ref={svgRef}></svg>
      <div style={{ display: 'flex', gap: '24px', marginTop: '18px', alignItems: 'center', justifyContent: 'center' }}>
        <span style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span style={{ width: 18, height: 6, background: '#235390', display: 'inline-block', borderRadius: 3 }}></span>
          <span style={{ fontSize: 14, color: '#235390', fontWeight: 600 }}>2019 Mean Temp (°F)</span>
        </span>
        <span style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span style={{ width: 18, height: 6, background: '#e74c3c', display: 'inline-block', borderRadius: 3 }}></span>
          <span style={{ fontSize: 14, color: '#e74c3c', fontWeight: 600 }}>2024 Mean Temp (°F)</span>
        </span>
      </div>
    </div>
  );
};

export default RadarChart; 