import React, { useEffect, useState } from 'react';
import './App.css';
import ReactFlipPage from 'react-flip-page'; // Import the flip page library
import BarChart from './components/ChartOne';
import CountryEmissionsChart from './components/ChartTwo';
import EuropeEmissionsChart from './components/ChartThree';
import RaceBarChart from './components/ChartFour';
import HeatMap from './components/ChartFive';
import WorldMapChart from './components/WorldMapGraph';
import AlluvialDiagram from './components/Alluvial';
import TimelineChart from './components/TimelineChart';
import RadarChart from './components/RadarChart';

const App = () => {
  const [currentSection, setCurrentSection] = useState(-1);
  const [currentPage, setCurrentPage] = useState(0);
  const [flipClass, setFlipClass] = useState("");
  const [rotation, setRotation] = useState(0);
  const [inRotation, setInRotation] = useState(0);
  var height = 25;
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='1' height='${height}'>
                 <line x1='0' y1='${height}' x2='1' y2='${height}' stroke='black' stroke-width='1px'/>
               </svg>`;

  const style = {
    backgroundImage: `url("data:image/svg+xml;utf8,${encodeURIComponent(svg)}")`,
  };
  const sections = [
    {
      title: "Section 1: Compare Categories",
      description: "This section compares CO₂ Emissions of different countries and visualize the data with different graphs.",
      graphs: [
        { component: <BarChart />, heading: "Top 10 Countries by CO₂ Emissions per Capita (2019)", description: "The graph is a bar chart visualizing the top 10 countries with the highest CO₂ emissions per capita in 2019. It uses data sourced from a CSV file to display the annual emissions per capita for each country. The chart is designed to highlight disparities in emissions levels, offering insights into global emission trends, with tooltips for enhanced interactivity and details on hover." },
        { component: <CountryEmissionsChart country="Qatar" />, heading: "Qatar's CO₂ emissions in period 2012-2022", description: "The CountryEmissionsChart component is a bar chart that visualizes CO₂ emissions per capita for Qatar from 2012 to 2022. It dynamically filters the data based on the country prop and creates a bar chart using D3.js, showcasing annual emission trends. The chart highlights emission patterns over the years, helping users analyze the country's environmental impact." },
        { component: <EuropeEmissionsChart />, heading: "CO₂ Emissions per Capita in European Countries Over Time", description: "The EuropeEmissionsChart component visualizes CO₂ emissions per capita trends for selected European countries over time using a line chart. It filters data for a predefined list of countries, plotting emissions from available years. Each country's emissions are represented as a line with a unique color, and a legend identifies the countries. This chart helps analyze and compare trends in emissions per capita across Europe, providing insights into environmental performance over time." },
        { component: <RaceBarChart />, heading: "Top 10 CO₂ Emitters Over the years", description: "The RaceBarChart component is a dynamic bar chart that visualizes the top 10 countries with the highest CO₂ emissions per capita for each year in the dataset. Using a 'race chart' animation, it displays emissions data year by year, transitioning smoothly to show changes over time. The chart includes country-specific colors, labels for emissions values, and a prominent year label to emphasize the current year being displayed, providing a visually engaging way to track historical trends in emissions." },
        { component: <HeatMap year={2022} />, heading: "CO₂ Emissions Heatmap (Top 10 Countries)", description: "The CO2Heatmap component is a heatmap visualization for CO₂ emissions, focusing on the top 10 countries with the highest total emissions for a specified year. The heatmap differentiates between emissions from fossil fuels and landuse changes, providing a detailed and visually appealing breakdown." },
      ],
    },
    {
      title: "Section 2: Alluvial Diagram",
      description: "This section utilizes the Alluvial Diagram to show the flow of CO₂ emissions.", 
      graphs: [
        { component: <AlluvialDiagram />, heading: "CO₂ Emissions by Continent, Country, and Source", description: "This alluvial diagram shows how CO₂ emissions flow between continents and countries in 2020. It displays different categories of emissions, like coal, oil, and land use, with links showing the amount of emissions from each category. The nodes represent continents, countries, and emission categories, and the width of the links changes based on the total emissions. This helps us see which countries are contributing the most to CO₂ emissions and how different sources affect them." },
      ],
    },
    {
      title: "Section 3: World Map",
      description: "This section depicts the CO₂ Emissions and puts it into a full world map.",
      graphs: [
        { component: <WorldMapChart />, heading: "World CO₂ Emissions Map (2020)", description: "This map shows the CO₂ emissions of countries around the world for the year 2020. Each country is colored using a green gradient, where lighter shades represent lower emissions and darker shades indicate higher emissions. When you hover over a country, a tooltip appears showing the total emissions in metric tons for that specific country. This visualization helps in understanding the distribution of emissions globally and highlights the countries contributing the most to CO₂ emissions." },
      ],
    },
    {
      title: "Section 4: Timeline",
      description: "This section shows the monthly minimum, maximum, and average temperatures for different states with differnet charts.",
      graphs: [
        { component: <TimelineChart />, heading: "New York 2023 Monthly Temperatures Timeline", description: "A line and scatter chart showing the monthly minimum, maximum, and mean temperatures for New York in 2023. From the charts, it doesn't seem like any big changes throughout the year, showing stable weather." },
        { component: <RadarChart />, heading: "Montana 2019 & 2024 Monthly Temperatures Radar Chart", description: "A radar (polar) chart showing the mean temperature for each month in Montana, 2029 and 2024. The radial grid quantifies the temperature for both the year with the difference of 5 years. Showing how on average the weather has become hotter." },
      ],
    },
  ];

  const handleNextPage = () => {
    if (currentPage < sections[currentSection].graphs.length - 1) {
      setCurrentPage(currentPage + 1);
      setRotation(prevRotation => prevRotation + 180);
      setInRotation(prevRotation => prevRotation - 180);

    }
  };

  const handlePreviousPage = () => {
    if (currentPage > 0) {
      setCurrentPage(currentPage - 1);
      setRotation(prevRotation => prevRotation - 180); 
      setInRotation(prevRotation => prevRotation + 180);
    }
  };
  useEffect(() => {
    const handleKeyDown = (event) => {
      if (event.key === "ArrowLeft") {
        handlePreviousPage();
      } else if (event.key === "ArrowRight") {
        handleNextPage();
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    // Cleanup listener on component unmount
    return () => {
      window.removeEventListener("keydown", handleKeyDown);
    };
  }, [currentPage, currentSection, sections]);


  return (
    <div className="App">
       {currentSection === -1 ? (
      <div className="cover-page">
        {/* Left Side (White Background) */}
        <div className="cover-left">
          {/* Nested Div with Book Image and Freely Positioned Text */}
          <div className="book-container">
            {/* <img src="./assets/book-cover.jpg" alt="Book Cover" className="book-image" /> */}
            <div className="text-overlay">
              <div className="section-links" style={{ top: "40%", left: "23%" }}>
                {sections.map((section, index) => (
                  <button
                    key={index}
                    className="section-button"
                    onClick={() => {
                      setCurrentSection(index);
                    }}
                  >
                    {section.title}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* Right Side with Linear Gradient and Additional Text */}
        <div className="cover-right">
          <div>
            <h1>About the Project</h1>
            <p>
              This project explores CO2 emissions data across various dimensions, visualized using advanced tools like D3.js.
            </p>
            <p>
              It contains 3 sections, each showing different type of visualization mainly focusing on CO₂ Emissions worldwide and over the years.
            </p>
            <p>
              Project Made in ReactJs.<br/>
              Hammad Aamir
            </p>
          </div>
        </div>
      </div>
  ) : (
    
    <div className="book">
        <div className="book-layout">
          {/* Static Section (Pinned Note) */}
          <div className="static-section">
            <div className="pin-top"></div> {/* Pin indicator at the top */}
            <h2>Section {currentSection + 1}</h2>
            <p>{sections[currentSection].title}</p>
            
            <p style={{padding: "0px", fontSize: "1.4rem"}} className="notes">
              {sections[currentSection].description}
            </p>
            <div className="navigation-buttons">
              <button style={{background: "linear-gradient(145deg, #e6d2a8, #e8d5a0)"}} onClick={() => setCurrentSection(-1)}>Back to Cover</button>
            </div>
            
            
          </div>


          {/* Book Content */}
          <div className="book-content">
            <div style={{ transform: `rotateY(${rotation}deg)` }} className={`book-page`}>
              <div style={{ transform: `rotateY(${inRotation}deg)` }} className="top-section">
              <div className="graph-navigation">
  <button onClick={handlePreviousPage} disabled={currentPage === 0}>
    Previous
  </button>
  <h2 className="graph-heading">{sections[currentSection].graphs[currentPage].heading}</h2>
  <button
    onClick={handleNextPage}
    disabled={currentPage === sections[currentSection].graphs.length - 1}
  >
    Next
  </button>
</div>

                <div className="graph-container">
                  {sections[currentSection].graphs[currentPage].component}
                </div>
              </div>
              <div style={{ transform: `rotateY(${inRotation}deg)` }} className="bottom-section">
                <p className="notes">
                  {sections[currentSection].graphs[currentPage].description}
                </p>
              </div>
              
            </div>
            {/* <div className="navigation-buttons">
              <button onClick={() => setCurrentSection(-1)}>Back to Cover</button>
              <button onClick={handlePreviousPage} disabled={currentPage === 0}>
                Previous
              </button>
              <button
                onClick={handleNextPage}
                disabled={currentPage === sections[currentSection].graphs.length - 1}
              >
                Next
              </button>
            </div> */}
          </div>
        </div>
      </div>
)}
    </div>
  );
};

export default App;
