import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

const EuropeEmissionsChart = () => {
  const svgRef = useRef(null);

  useEffect(() => {
    // Remove any existing tooltip
    d3.select('.racebar-tooltip').remove();
    // Create tooltip div
    const tooltip = d3.select('body')
      .append('div')
      .attr('class', 'racebar-tooltip')
      .style('position', 'absolute')
      .style('background', '#fffbe9')
      .style('color', '#6b4f27')
      .style('border', '1.5px solid #d6c7b0')
      .style('border-radius', '6px')
      .style('padding', '6px 12px')
      .style('font-family', 'Georgia, Times New Roman, Times, serif')
      .style('font-size', '0.95rem')
      .style('box-shadow', '0 2px 8px rgba(120, 90, 40, 0.10)')
      .style('pointer-events', 'none')
      .style('z-index', 1000)
      .style('display', 'none');

    // Load the CSV data
    d3.csv(process.env.PUBLIC_URL + "/co-emissions-per-capita.csv").then((data) => {
      // List of European countries (can be extended)
      const europeanCountries = [
        'Germany', 'France', 'United Kingdom', 'Italy', 'Spain',
        'Netherlands', 'Poland', 'Sweden', 'Norway', 'Finland',
        'Denmark', 'Portugal', 'Greece', 'Ireland', 'Austria',
        'Belgium', 'Switzerland', 'Czechia'
      ];

      // Filter data for European countries
      const filteredData = data
        .filter((d) => europeanCountries.includes(d['Entity']))
        .map((d) => ({
          country: d['Entity'],
          year: +d['Year'],
          emissions: +d['Annual_CO2_emissions_(per_capita)'],
        }));

      // Group data by country
      const groupedData = d3.group(filteredData, (d) => d.country);

      // Set dimensions and margins
      const width = 900;
      const height = 500;
      const margin = { top: 20, right: 50, bottom: 50, left: 70 };

      // Clear any previous content
      d3.select(svgRef.current).selectAll('*').remove();

      // Create the SVG container
      const svg = d3
        .select(svgRef.current)
        .attr('width', width + margin.left + margin.right)
        .attr('height', height + margin.top + margin.bottom)
        .append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

      // Define scales
      const x = d3
        .scaleLinear()
        .domain(d3.extent(filteredData, (d) => d.year))
        .range([0, width]);

      const y = d3
        .scaleLinear()
        .domain([0, d3.max(filteredData, (d) => d.emissions)])
        .nice()
        .range([height, 0]);

      // Add X-axis
      svg
        .append('g')
        .attr('transform', `translate(0,${height})`)
        .call(d3.axisBottom(x).tickFormat(d3.format('d')));

      // Add Y-axis
      svg.append('g').call(d3.axisLeft(y));

      // Add labels
      svg
        .append('text')
        .attr('x', width / 2)
        .attr('y', height + margin.bottom - 10)
        .attr('text-anchor', 'middle')
        .text('Year');

      svg
        .append('text')
        .attr('x', -height / 2)
        .attr('y', -margin.left + 15)
        .attr('text-anchor', 'middle')
        .attr('transform', 'rotate(-90)')
        .text('CO₂ Emissions per Capita (tons)');

      // Define line generator
      const line = d3
        .line()
        .x((d) => x(d.year))
        .y((d) => y(d.emissions));

      // Draw lines for each country
      const color = d3.scaleOrdinal(d3.schemeCategory10);

      groupedData.forEach((values, country) => {
        svg
          .append('path')
          .datum(values)
          .attr('class', 'country-line')
          .attr('data-country', country)
          .attr('fill', 'none')
          .attr('stroke', '#bbb') // grey by default
          .attr('stroke-width', 2)
          .attr('opacity', 0.7)
          .attr('d', line)
          .on('mouseover', function (event) {
            d3.select(this)
              .attr('stroke', color(country))
              .attr('opacity', 1)
              .attr('stroke-width', 4);
            svg.selectAll('.country-line')
              .filter(function() { return this !== d3.select(this).node(); })
              .attr('opacity', 0.2)
              .attr('stroke', '#bbb')
              .attr('stroke-width', 2);
            // Tooltip
            const latest = values[values.length - 1];
            tooltip
              .style('display', 'block')
              .html(`<strong>${country}</strong><br/>Year: ${latest.year}<br/>Emissions: ${latest.emissions.toFixed(2)} tons`)
              .style('left', (event.clientX + 16) + 'px')
              .style('top', (event.clientY - 16) + 'px');
          })
          .on('mousemove', function(event) {
            tooltip
              .style('left', (event.clientX + 16) + 'px')
              .style('top', (event.clientY - 16) + 'px');
          })
          .on('mouseout', function () {
            svg.selectAll('.country-line')
              .attr('stroke', '#bbb')
              .attr('opacity', 0.7)
              .attr('stroke-width', 2);
            tooltip.style('display', 'none');
          })
          .attr('opacity', 0)
          .transition()
          .duration(1000)
          .delay(Math.random() * 1000) // Staggered animation
          .attr('opacity', 0.7);
      });

      // Add legend
      const legend = svg.append('g').attr('transform', `translate(20, 0)`);

      let legendIndex = 0;
      groupedData.forEach((values, country) => {
        // Legend color box
        legend
          .append('rect')
          .attr('x', -5)
          .attr('y', legendIndex * 20)
          .attr('width', 10)
          .attr('height', 10)
          .attr('fill', color(country))
          .attr('class', 'legend-item')
          .attr('data-country', country)
          .on('mouseover', function (event) {
            svg.selectAll('.country-line')
              .attr('stroke', function() {
                return d3.select(this).attr('data-country') === country ? color(country) : '#bbb';
              })
              .attr('opacity', function() {
                return d3.select(this).attr('data-country') === country ? 1 : 0.2;
              })
              .attr('stroke-width', function() {
                return d3.select(this).attr('data-country') === country ? 4 : 2;
              });
            // Tooltip
            const latest = values[values.length - 1];
            tooltip
              .style('display', 'block')
              .html(`<strong>${country}</strong><br/>Year: ${latest.year}<br/>Emissions: ${latest.emissions.toFixed(2)} tons`)
              .style('left', (event.clientX + 16) + 'px')
              .style('top', (event.clientY - 16) + 'px');
          })
          .on('mousemove', function(event) {
            tooltip
              .style('left', (event.clientX + 16) + 'px')
              .style('top', (event.clientY - 16) + 'px');
          })
          .on('mouseout', function () {
            svg.selectAll('.country-line')
              .attr('stroke', '#bbb')
              .attr('opacity', 0.7)
              .attr('stroke-width', 2);
            tooltip.style('display', 'none');
          });

        // Legend text
        legend
          .append('text')
          .attr('x', 15)
          .attr('y', legendIndex * 20 + 9)
          .text(country)
          .attr('font-size', '10px')
          .attr('alignment-baseline', 'middle')
          .attr('class', 'legend-item')
          .attr('data-country', country)
          .on('mouseover', function (event) {
            svg.selectAll('.country-line')
              .attr('stroke', function() {
                return d3.select(this).attr('data-country') === country ? color(country) : '#bbb';
              })
              .attr('opacity', function() {
                return d3.select(this).attr('data-country') === country ? 1 : 0.2;
              })
              .attr('stroke-width', function() {
                return d3.select(this).attr('data-country') === country ? 4 : 2;
              });
            // Tooltip
            const latest = values[values.length - 1];
            tooltip
              .style('display', 'block')
              .html(`<strong>${country}</strong><br/>Year: ${latest.year}<br/>Emissions: ${latest.emissions.toFixed(2)} tons`)
              .style('left', (event.clientX + 16) + 'px')
              .style('top', (event.clientY - 16) + 'px');
          })
          .on('mousemove', function(event) {
            tooltip
              .style('left', (event.clientX + 16) + 'px')
              .style('top', (event.clientY - 16) + 'px');
          })
          .on('mouseout', function () {
            svg.selectAll('.country-line')
              .attr('stroke', '#bbb')
              .attr('opacity', 0.7)
              .attr('stroke-width', 2);
            tooltip.style('display', 'none');
          });

        legendIndex++;
      });
    });
  }, []);

  return (
    <div>
      {/* <h2>CO₂ Emissions per Capita in European Countries Over Time</h2> */}
      <svg ref={svgRef}></svg>
    </div>
  );
};

export default EuropeEmissionsChart;
