import React, { useEffect, useRef } from 'react';
import * as d3 from 'd3';

const CountryEmissionsChart = ({ country }) => {
  const svgRef = useRef(null);

  useEffect(() => {
    // Load the CSV data
    d3.csv(process.env.PUBLIC_URL + "/co-emissions-per-capita.csv").then((data) => {
      // Filter data for the selected country and years 2012 to 2022
      const filteredData = data
        .filter((d) => d['Entity'] === country && +d['Year'] >= 2012 && +d['Year'] <= 2022)
        .map((d) => ({
          year: d['Year'],
          emissions: +d['Annual_CO2_emissions_(per_capita)'],
        }));

      // Set dimensions and margins for the chart
      const width = 800;
      const height = 500;
      const margin = { top: 20, right: 30, bottom: 40, left: 100 };

      // Create scales for x and y axes
      const x = d3
        .scaleBand()
        .domain(filteredData.map((d) => d.year))
        .range([0, width])
        .padding(0.1);

      const y = d3
        .scaleLinear()
        .domain([0, d3.max(filteredData, (d) => d.emissions)])
        .range([height, 0]);

      // Clear any previous SVG content if it exists
      d3.select(svgRef.current).selectAll('*').remove();

      // Create the SVG container
      const svg = d3
        .select(svgRef.current)
        .attr('width', width + margin.left + margin.right)
        .attr('height', height + margin.top + margin.bottom)
        .append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

      // Add X-axis
      svg
        .append('g')
        .attr('transform', `translate(0,${height})`)
        .call(d3.axisBottom(x));

      // Add Y-axis
      svg.append('g').call(d3.axisLeft(y));
      const tooltip = d3.select("body").append("div")
      .attr('class', 'racebar-tooltip')
      .style('position', 'absolute')
      .style('background', '#fffbe9')
      .style('color', '#6b4f27')
      .style('border', '1.5px solid #d6c7b0')
      .style('border-radius', '6px')
      .style('padding', '6px 12px')
      .style('font-family', 'Georgia, Times New Roman, Times, serif')
      .style('font-size', '0.95rem')
      .style('box-shadow', '0 2px 8px rgba(120, 90, 40, 0.10)')
      .style('pointer-events', 'none')
      .style('z-index', 1000)
      .style('opacity', 0);
      // Create bars for the chart
      svg
        .selectAll('rect')
        .data(filteredData)
        .enter()
        .append('rect')
        .attr('x', (d) => x(d.year))
        .attr('y', (d) => y(d.emissions))
        .attr('width', x.bandwidth())
        .attr('height', (d) => height - y(d.emissions))
        .attr('fill', '#4285F4')
        .on("mouseover", function (event, d) {
          tooltip.transition().duration(200).style("opacity", 0.95);
          tooltip.html(`<strong>Year:</strong> ${d["year"]}<br><strong>Emissions:</strong> ${d["emissions"].toFixed(2)} tons/capita`)
              .style("left", (event.clientX + 16) + "px")
              .style("top", (event.clientY - 16) + "px");

          d3.select(this)
            .style("transform", "scale(1.01,1.01)")
            .style("transform-origin", "50% 50%")
            .transition()
            .duration(150)
            .style("opacity", 0.8)
        })
        .on("mouseout", function () {
          d3.select(this)
            .style("transform", "scale(1,1)")
            .style("transform-origin", "50% 50%")
            .transition()
            .duration(500)
            .style("opacity", 1)

            tooltip.transition().duration(500).style("opacity", 0);
        });
    });
  }, [country]);

  return (
    <div>
      {/* <h2>CO₂ Emissions per Capita in {country} (2012-2022)</h2> */}
      <svg ref={svgRef}></svg>
    </div>
  );
};

export default CountryEmissionsChart;
