import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { feature } from 'topojson-client';

const WorldMapChart = () => {
  const svgRef = useRef(null);
  const [geoData, setGeoData] = useState(null);
  const [maxEmission, setMaxEmission] = useState(0);

  useEffect(() => {
    const fetchData = async () => {
      const url = 'https://raw.githubusercontent.com/owid/co2-data/master/owid-co2-data.csv';
      const worldGeoJSON = 'https://raw.githubusercontent.com/holtzy/D3-graph-gallery/master/DATA/world.geojson';

      try {
        // Fetch emissions and GeoJSON data
        const [rawCSV, geoResponse] = await Promise.all([
          fetch(url).then((res) => res.text()),
          fetch(worldGeoJSON).then((res) => res.json()),
        ]);

        const data = d3.csvParse(rawCSV, d3.autoType);
        const selectedYear = 2020;
        const filteredData = data.filter((d) => d.year === selectedYear);

        // Map emissions data to GeoJSON
        geoResponse.features.forEach((feature) => {
          const countryData = filteredData.find((d) => d.iso_code === feature.id);
          feature.properties.emissions = countryData ? countryData.co2 || 0 : 0;
        });

        setGeoData(geoResponse);
        const maxEmissionValue = d3.max(geoResponse.features, (d) => d.properties.emissions);
        setMaxEmission(maxEmissionValue);
      } catch (error) {
        console.error('Error fetching data:', error);
      }
    };

    fetchData();
  }, []);

  useEffect(() => {
    if (!geoData) return;

    // Set up map dimensions
    const width = 900;
    const height = 600;

    const svg = d3.select(svgRef.current);
    svg.selectAll('*').remove();

    const projection = d3.geoMercator().scale(130).translate([width / 2, height / 1.5]);
    const path = d3.geoPath().projection(projection);

    // Green color scale for emissions
    const colorScale = d3.scaleSequential(d3.interpolateGreens).domain([0, maxEmission]);

    // Draw the map
    const countries = svg
      .selectAll('path')
      .data(geoData.features)
      .enter()
      .append('path')
      .attr('d', path)
      .attr('fill', (d) => {
        const value = d.properties.emissions;
        return value > 0 ? colorScale(value) : '#ccc';
      })
      .attr('stroke', '#333') // Darker stroke color
      .attr('stroke-width', 1)
      .on('mouseover', (event, d) => {
        const tooltip = d3.select('#tooltip');
        tooltip
          .style('opacity', 1)
          .html(`
            Country: ${d.properties.name}<br>
            Total Emissions: ${d.properties.emissions || 0} Mtons
          `)
          .style('left', `${event.pageX - (width / 2) + 150}px`)
          .style('top', `${event.pageY + 20}px`);

        // Highlight the hovered country
        d3.select(event.target)
          .raise()
          .transition()
          .duration(300)
          .attr('transform', 'scale(1.01)')
          .attr('stroke-width', '2')
          .attr('stroke', '#FF5733'); // Change color on hover

        // Change opacity of other countries
        countries.style('opacity', 0.8); // Set all countries to 50% opacity
        d3.select(event.target).style('opacity', 1); // Keep the hovered country at full opacity
      })
      .on('mouseout', (event, d) => {
        d3.select('#tooltip').style('opacity', 0);

        // Reset transformations
        d3.select(event.target)
          .transition()
          .duration(300)
          .attr('transform', 'scale(1)')
          .attr('stroke', '#333')
          .attr('stroke-width', '1')
          .attr('fill', (d) => {
            const value = d.properties.emissions;
            return value > 0 ? colorScale(value) : '#ccc';
          });

        // Reset opacity of all countries
        countries.style('opacity', 1);
      });
  }, [geoData, maxEmission]);

  return (
    <div>
      <svg ref={svgRef} width={900} height={600}></svg>
      <div
        id="tooltip"
        style={{
          position: 'absolute',
          background: '#f0e284',
          color: '#000',
          padding: '10px',
          border: '1px solid #ccc',
          borderRadius: '5px',
          opacity: 0,
        }}
      ></div>
    </div>
  );
};

export default WorldMapChart;
